import requests, sys, time, uuid

BASE = '{{TESTVDB_DB_URL}}'
c = 'TestReplicationFactor_' + uuid.uuid4().hex[:8]

# Clean up first
requests.delete(f'{BASE}/v1/schema/{c}')

# Test 1: replicationConfig.factor = 0 (below minimum)
print("=== TEST 1: replicationConfig.factor = 0 ===")
payload = {
    "class": c,
    "vectorizer": "none",
    "vectorIndexConfig": {
        "distance": "cosine",
        "efConstruction": 128,
        "maxConnections": 32,
        "dynamicEfMin": 100,
        "dynamicEfMax": 500,
        "dynamicEfFactor": 8,
        "cleanupIntervalSeconds": 300,
        "flatSearchCutoff": 40000
    },
    "replicationConfig": {
        "factor": 0
    },
    "multiTenancyConfig": {
        "enabled": False
    },
    "properties": [
        {"name": "text", "dataType": ["text"]}
    ]
}

r = requests.post(f'{BASE}/v1/schema', json=payload)
if r.status_code == 200:
    print(f'[DEFECT: ILLEGAL_SUCCESS] Server accepted replicationConfig.factor=0 (below minimum)')
    print(f'Response: {r.text}')
    sys.exit(1)
else:
    print(f'Server correctly rejected replicationConfig.factor=0: status={r.status_code}, msg={r.text}')

# Clean up
requests.delete(f'{BASE}/v1/schema/{c}')
sys.exit(0)

